import { NextRequest, NextResponse } from 'next/server';
import * as XLSX from 'xlsx';
import { db } from '@/lib/db';
import { setCurrentPeriod } from '@/lib/dashboard-service';
import { normalizeEnseigne, similarityScore } from '@/lib/normalize-enseigne';

// Augmente le timeout Vercel à 60s (au lieu de 10s par défaut)
export const maxDuration = 60;

// POST /api/import
// Body: multipart/form-data avec champs "file" (Excel), "forceType", "forceAgent", "replaceDuplicates", "detectOnly"
export async function POST(req: NextRequest) {
  console.log('=== POST /api/import ===');
  try {
    const formData = await req.formData();
    const file = formData.get('file');
    const mappingRaw = formData.get('mapping') as string | null;
    const detectOnly = formData.get('detectOnly') === 'true';
    const forceType = (formData.get('forceType') as string | null) ?? 'auto';
    const forceAgent = (formData.get('forceAgent') as string | null) ?? '';
    const replaceDuplicates = formData.get('replaceDuplicates') === 'true';

    if (!file || !(file instanceof File)) {
      return NextResponse.json(
        { ok: false, error: 'Aucun fichier reçu.' },
        { status: 400 }
      );
    }

    console.log(`Fichier reçu : ${file.name} (${file.size} octets) detectOnly=${detectOnly} forceType=${forceType} forceAgent=${forceAgent} replaceDuplicates=${replaceDuplicates}`);

    let buffer: ArrayBuffer;
    try {
      buffer = await file.arrayBuffer();
    } catch {
      return NextResponse.json(
        { ok: false, error: 'Impossible de lire le fichier. Vérifiez qu\'il n\'est pas corrompu.' },
        { status: 400 }
      );
    }

    let workbook: XLSX.WorkBook;
    try {
      workbook = XLSX.read(buffer, { type: 'array', cellDates: true });
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      return NextResponse.json(
        { ok: false, error: `Format Excel non reconnu : ${msg}` },
        { status: 400 }
      );
    }

    console.log(`Feuilles détectées : ${workbook.SheetNames.join(', ')}`);

    // Cherche la feuille VENTES, sinon une feuille contenant "vente", sinon la 1ère
    let sheetName: string = workbook.SheetNames[0] ?? '';
    if (workbook.SheetNames.includes('VENTES')) {
      sheetName = 'VENTES';
    } else {
      const venteSheet = workbook.SheetNames.find((n) => /vente/i.test(n));
      if (venteSheet) sheetName = venteSheet;
    }
    console.log(`Feuille utilisée : ${sheetName}`);

    const sheet = workbook.Sheets[sheetName];

    // Détecte où sont les en-têtes (scanne 5 premières lignes)
    let headerRowIdx = 0;
    let headers: string[] = [];
    for (let tryRow = 0; tryRow < 5; tryRow++) {
      try {
        const testRows = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, {
          raw: false,
          defval: null,
          range: tryRow,
        });
        if (testRows.length === 0) continue;
        const testHeaders = Object.keys(testRows[0]).map((h) => h.toLowerCase());
        const hasDate = testHeaders.some((h) => h.includes('date'));
        const hasOther = testHeaders.some((h) =>
          h.includes('enseigne') || h.includes('client') || h.includes('montant') || h.includes('ca') || h.includes('ht')
        );
        if (hasDate && hasOther) {
          headerRowIdx = tryRow;
          headers = Object.keys(testRows[0]);
          break;
        }
      } catch {
        continue;
      }
    }

    if (headers.length === 0) {
      const rows = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, {
        raw: false,
        defval: null,
      });
      if (rows.length === 0) {
        return NextResponse.json(
          { ok: false, error: `La feuille "${sheetName}" ne contient aucune donnée.` },
          { status: 400 }
        );
      }
      headers = Object.keys(rows[0]);
    }

    console.log(`En-têtes détectés (ligne ${headerRowIdx + 1}) : ${headers.join(', ')}`);

    // Lit les lignes en raw=false (texte) pour bien gérer les décimales françaises (436,16 vs 43616)
    const rows = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet, {
      raw: false,
      defval: null,
      range: headerRowIdx,
    });

    // Helper de normalisation (gère les accents et apostrophes)
    const normalize = (s: string) =>
      s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[''`]/g, '').trim();

    // Auto-détection des colonnes (avec unicité)
    const usedCols = new Set<string>();
    const findCol = (patterns: string[]): string | null => {
      for (const p of patterns) {
        const pl = normalize(p);
        const found = headers.find((h) => {
          if (usedCols.has(h)) return false;
          const hl = normalize(h);
          return hl === pl || hl.includes(pl);
        });
        if (found) {
          usedCols.add(found);
          return found;
        }
      }
      return null;
    };

    // Ordre important : du plus spécifique au moins spécifique pour éviter les conflits
    const auto = {
      taux: findCol(['% MARGE COMMERCIALE','MARGE COMMERCIALE','TAUX']),
      commission: findCol(['MONTANT COMMISSION','COMMISSION']),
      bl: findCol(['NUMERO BL','N° BL','NUMERO','N BL','BON DE LIVRAISON','BL','RÉFÉRENCE','REFERENCE','REF']),
      agent: findCol(['COMMERCIAL','AGENT','REPRESENTANT','VENDEUR']),
      reference: findCol(['RÉFÉRENCE','REFERENCE','REF']),
      type: findCol(['TYPE','CANAL','CIRCUIT']),
      enseigne: findCol(['ENSEIGNE','CLIENT','MAGASIN']),
      date: findCol(['DATE']),
      ht: findCol(['MONTANT HT','CA HT','MT HT','HT']),
      ttc: findCol(['MONTANT TTC','CA TTC','MT TTC','TTC']),
      // Ne pas détecter MOIS/ANNEE : on utilise toujours la date parsée
      mois: null as string | null,
      annee: null as string | null,
    };

    let mapping: typeof auto;
    if (mappingRaw) {
      try {
        const p = JSON.parse(mappingRaw);
        mapping = {
          taux: p.taux ?? auto.taux,
          commission: p.commission ?? auto.commission,
          bl: p.bl ?? auto.bl,
          agent: p.agent ?? auto.agent,
          reference: p.reference ?? auto.reference,
          type: p.type ?? auto.type,
          enseigne: p.enseigne ?? auto.enseigne,
          date: p.date ?? auto.date,
          ht: p.ht ?? auto.ht,
          ttc: p.ttc ?? auto.ttc,
          mois: null, // forcé : on n'utilise jamais de colonnes MOIS/ANNEE
          annee: null,
        };
        console.log('Mapping utilisateur + auto-détection :', mapping);
      } catch {
        return NextResponse.json(
          { ok: false, error: 'Mapping invalide (JSON malformé).' },
          { status: 400 }
        );
      }
    } else {
      mapping = auto;
      console.log('Mapping auto-détecté :', mapping);
    }

    // Validation
    if (!mapping.date) {
      return NextResponse.json(
        { ok: false, error: `Colonne "DATE" introuvable. Colonnes détectées : ${headers.join(', ')}`, detectedColumns: headers, mapping },
        { status: 400 }
      );
    }
    if (!mapping.ht && !mapping.ttc) {
      return NextResponse.json(
        { ok: false, error: `Aucune colonne de montant (HT ou TTC) détectée. Colonnes : ${headers.join(', ')}`, detectedColumns: headers, mapping },
        { status: 400 }
      );
    }
    if (!mapping.enseigne) {
      return NextResponse.json(
        { ok: false, error: `Aucune colonne "ENSEIGNE" ou "CLIENT" détectée. Colonnes : ${headers.join(', ')}`, detectedColumns: headers, mapping },
        { status: 400 }
      );
    }

    // Charge les données existantes — optimisé: ne charge que les clés
    // de déduplication (pas toutes les ventes) et les enseignes existantes
    console.log('Chargement des clés existantes...');
    const existingKeys = new Set(
      (await db.sale.findMany({ select: { deduplicationKey: true }, orderBy: { date: 'desc' } })).map((s) => s.deduplicationKey)
    );
    console.log(`Clés en base: ${existingKeys.size}`);
    const existingEnseignes = await db.enseigne.findMany({ select: { name: true, type: true, agent: true } });
    const enseigneTypeMap = new Map(existingEnseignes.map((e) => [e.name, e.type]));
    const enseigneAgentMap = new Map(existingEnseignes.map((e) => [e.name, e.agent]));

    // === Détection intelligente des doublons d'enseignes ===
    // Pour chaque nom entrant, on résout le nom canonique à utiliser en
    // comparant avec les enseignes déjà en base (match exact / normalisé / similaire).
    // - Si un match est trouvé : on utilise le nom canonique existant (pas de création de doublon)
    // - Si aucun match : on crée une nouvelle enseigne avec le nom entrant
    // Les substitutions sont enregistrées pour reporting dans la réponse.
    const existingNames = existingEnseignes.map((e) => e.name);
    // Pré-calcule les formes normalisées des enseignes existantes pour gagner du temps
    const existingNormMap = new Map<string, string>(); // normalized → original name
    for (const name of existingNames) {
      const n = normalizeEnseigne(name);
      if (n && !existingNormMap.has(n)) existingNormMap.set(n, name);
    }
    const canonicalResolutions = new Map<string, { incoming: string; canonical: string; confidence: number; status: string }>();
    let duplicateDetectedCount = 0;
    const resolveIncoming = (incoming: string): string => {
      if (!incoming?.trim()) return incoming;
      const trimmed = incoming.trim();
      // Cache
      if (canonicalResolutions.has(trimmed)) {
        return canonicalResolutions.get(trimmed)!.canonical;
      }
      const lower = trimmed.toLowerCase();
      // 1. Exact case-insensitive
      const exact = existingNames.find((n) => n.toLowerCase() === lower);
      if (exact) {
        canonicalResolutions.set(trimmed, { incoming: trimmed, canonical: exact, confidence: 1, status: 'exact' });
        return exact;
      }
      // 2. Normalized match
      const incomingNorm = normalizeEnseigne(trimmed);
      if (incomingNorm) {
        const normMatch = existingNormMap.get(incomingNorm);
        if (normMatch) {
          canonicalResolutions.set(trimmed, { incoming: trimmed, canonical: normMatch, confidence: 0.95, status: 'normalized' });
          duplicateDetectedCount++;
          return normMatch;
        }
      }
      // 3. Similar match (seuil 0.85)
      let bestMatch: string | null = null;
      let bestScore = 0;
      for (const n of existingNames) {
        const score = similarityScore(trimmed, n);
        if (score > bestScore) { bestScore = score; bestMatch = n; }
      }
      if (bestMatch && bestScore >= 0.85) {
        canonicalResolutions.set(trimmed, { incoming: trimmed, canonical: bestMatch, confidence: bestScore, status: 'similar' });
        duplicateDetectedCount++;
        return bestMatch;
      }
      // 4. Nouveau
      canonicalResolutions.set(trimmed, { incoming: trimmed, canonical: trimmed, confidence: 0, status: 'new' });
      return trimmed;
    };
    const allAgents = await db.agent.findMany({ where: { isActive: true } });
    const activeAgents = allAgents.map((a) => ({ name: a.name }));
    // Récupère les taux par agent (pour KOOK'S = 0% / 0%)
    const agentRateMap = new Map<string, { direct: number; centrale: number }>(
      allAgents.map((a) => [a.name, { direct: a.defaultDirectRate, centrale: a.defaultCentraleRate }])
    );
    // Trouve l'agent KOOK'S (fallback par défaut pour les ventes sans commercial)
    const kooksAgent = allAgents.find((a) => /kook/i.test(a.name));
    const fallbackAgent = kooksAgent?.name ?? 'KOOK\'S';
    console.log(`Clés déjà en base : ${existingKeys.size}, enseignes : ${existingEnseignes.length}, agents actifs : ${activeAgents.length}, fallback : ${fallbackAgent}`);

    const toInsert: Array<{
      blNumber: string | null;
      deduplicationKey: string;
      date: Date;
      enseigne: string;
      type: string;
      agent: string;
      amountHT: number;
      amountTTC: number;
      rate: number;
      commission: number;
      month: number;
      year: number;
    }> = [];
    const newEnseignes = new Map<string, { name: string; type: string; agent: string }>();
    let skippedNoDate = 0, skippedNoAmount = 0, skippedDuplicate = 0, skippedInvalid = 0;
    const errors: string[] = [];

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const dateRaw = mapping.date ? row[mapping.date] : null;
      const blRaw = mapping.bl ? row[mapping.bl] : null;
      const enseigneRaw = mapping.enseigne ? row[mapping.enseigne] : null;
      const typeRaw = mapping.type ? row[mapping.type] : null;
      const agentRaw = mapping.agent ? row[mapping.agent] : null;
      const htRaw = mapping.ht ? row[mapping.ht] : null;
      const ttcRaw = mapping.ttc ? row[mapping.ttc] : null;
      const tauxRaw = mapping.taux ? row[mapping.taux] : null;
      const commissionRaw = mapping.commission ? row[mapping.commission] : null;

      const toStr = (v: unknown): string => (v ? String(v).trim() : '');
      const toNum = (v: unknown): number => {
        if (typeof v === 'number') return v;
        if (typeof v === 'string') {
          // Gère les formats français : "1 234,56 €" → 1234.56
          const cleaned = v.replace(/\s/g, '').replace(/€/g, '').replace(',', '.');
          const n = parseFloat(cleaned);
          return isNaN(n) ? 0 : n;
        }
        return 0;
      };

      // Parsing date : gère Date, nombre (Excel serial), string (DD/MM/YYYY ou ISO)
      let date: Date | null = null;
      if (dateRaw instanceof Date) {
        date = dateRaw;
      } else if (typeof dateRaw === 'number') {
        const epoch = new Date(Date.UTC(1899, 11, 30));
        date = new Date(epoch.getTime() + dateRaw * 86400000);
      } else if (typeof dateRaw === 'string' && dateRaw.trim()) {
        const t = dateRaw.trim();
        // Format DD/MM/YYYY ou DD-MM-YYYY
        const m = t.match(/^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})$/);
        if (m) {
          const d = parseInt(m[1], 10);
          const mo = parseInt(m[2], 10);
          let y = parseInt(m[3], 10);
          if (y < 100) y += 2000;
          date = new Date(y, mo - 1, d);
        } else {
          const p = new Date(t);
          if (!isNaN(p.getTime())) date = p;
        }
      }

      if (!date || isNaN(date.getTime()) || date.getFullYear() < 2020) {
        skippedNoDate++;
        continue;
      }

      const enseigneRaw2 = toStr(enseigneRaw);
      if (!enseigneRaw2 || /^(total|totaux|somme)$/i.test(enseigneRaw2)) {
        skippedInvalid++;
        continue;
      }
      // === Résolution intelligente du nom canonique ===
      // Si le nom entrant correspond à un client déjà en base (par normalisation ou similarité),
      // on utilise le nom canonique existant — éviter la création de doublons à l'import.
      const enseigne = resolveIncoming(enseigneRaw2);

      const amountHT = toNum(htRaw);
      const amountTTC = toNum(ttcRaw);
      // Si HT absent mais TTC présent : estimer HT = TTC / 1.056 (TVA 5.6% alimentaire)
      const finalHT = amountHT || (amountTTC ? amountTTC / 1.056 : 0);
      if (finalHT === 0) {
        skippedNoAmount++;
        continue;
      }

      // === Détection du type Centrale/Direct ===
      // Priorité : forceType > type en base (enseigne) > type dans le fichier > auto-détection par nom
      const ne = normalize(enseigne);
      const isCentrale = [
        'otera','scapest','scachap','scaouest','aldouest',
        'centra approvi','cooperative approvisionnement','societe cooperative dapprovi'
      ].some((p) => ne.includes(p));

      let type = '';
      if (forceType && forceType !== 'auto') {
        type = forceType;
      } else if (enseigneTypeMap.has(enseigne)) {
        type = enseigneTypeMap.get(enseigne)!;
      } else {
        type = toStr(typeRaw) || (isCentrale ? 'Centrale' : 'Direct');
      }

      // === Détection de l'agent ===
      // Priorité : forceAgent > colonne agent du fichier > extraction depuis référence > fallback KOOK'S
      // (KOOK'S est l'entreprise elle-même — toute vente sans commercial lui est rattachée)
      let agent = (forceAgent && forceAgent.trim()) || toStr(agentRaw);
      if (!agent && mapping.reference) {
        const ref = toStr(row[mapping.reference]);
        // Cherche "via XXX" ou "par XXX" dans la référence
        const m2 = ref.match(/\b(?:via|par)\s+([A-Z][A-Z\s&]{2,30})/);
        if (m2) {
          agent = m2[1].trim().split(/\s+(?:À|A|ET|DE|POUR)\s+/)[0].trim();
        }
        // Cherche le nom d'un agent actif dans la référence
        if (!agent) {
          const ru = ref.toUpperCase();
          for (const a of activeAgents) {
            if (ru.includes(a.name.toUpperCase())) {
              agent = a.name;
              break;
            }
          }
        }
      }
      if (!agent) agent = fallbackAgent;

      // === Taux de commission ===
      // Règle Kooks : utilise les taux de l'agent (defaultDirectRate / defaultCentraleRate)
      // - CAP FRAIS & BROCARD : 7% Direct, 5% Centrale
      // - KOOK'S : 0% (ventes maison sans commercial)
      const explicitRate = toNum(tauxRaw);
      const agentDefaults = agentRateMap.get(agent);
      const defaultRate = type === 'Centrale'
        ? (agentDefaults?.centrale ?? 0.05)
        : (agentDefaults?.direct ?? 0.07);
      const rate = explicitRate > 0
        ? (explicitRate > 1 ? explicitRate / 100 : explicitRate)
        : defaultRate;

      // === Montant commission ===
      const explicitCommission = toNum(commissionRaw);
      const commission = explicitCommission > 0 ? explicitCommission : finalHT * rate;

      // BL optionnel
      const blNumber = blRaw ? toStr(blRaw) : null;

      // deduplicationKey : BL+agent si BL présent, sinon hash incluant l'agent
      // (l'agent est inclus pour éviter les faux doublons entre CAP FRAIS et BROCARD)
      const deduplicationKey = blNumber
        ? `${blNumber}|${agent}`
        : `${date.toISOString().split('T')[0]}|${enseigne}|${type}|${finalHT.toFixed(2)}|${agent}`;

      // Vérifie doublons
      if (!replaceDuplicates && existingKeys.has(deduplicationKey)) {
        skippedDuplicate++;
        continue;
      }
      if (toInsert.some((v) => v.deduplicationKey === deduplicationKey)) {
        skippedDuplicate++;
        continue;
      }

      toInsert.push({
        blNumber,
        deduplicationKey,
        date,
        enseigne,
        type,
        agent,
        amountHT: finalHT,
        amountTTC: amountTTC || finalHT * 1.056,
        rate,
        commission,
        // TOUJOURS utiliser la date parsée (jamais de colonnes MOIS/ANNEE)
        month: date.getMonth() + 1,
        year: date.getFullYear(),
      });

      if (!newEnseignes.has(enseigne)) {
        newEnseignes.set(enseigne, { name: enseigne, type, agent });
      } else {
        // Si l'enseigne est déjà dans newEnseignes, met à jour l'agent si la nouvelle vente
        // a un agent plus spécifique (forceAgent ou colonne agent du fichier)
        const existing = newEnseignes.get(enseigne)!;
        // Si la nouvelle vente a un agent (forceAgent ou agentRaw) et l'existant est le fallback, on prend le nouveau
        if ((forceAgent?.trim() || toStr(agentRaw)) && existing.agent === fallbackAgent) {
          existing.agent = agent;
          existing.type = type;
        }
      }
    }

    // Met à jour les enseignes EXISTANTES dont l'agent a changé
    // (utile quand on importe un fichier de KOOK'S : les enseignes déjà en base
    //  sous CAP FRAIS ou BROCARD mais ayant des ventes KOOK'S doivent être réaffectées)
    let enseignesUpdated = 0;
    for (const [name, newData] of newEnseignes.entries()) {
      const existingAgent = enseigneAgentMap.get(name);
      // Met à jour l'agent si : pas d'agent existant, OU agent existant = fallback,
      // OU nouvelle vente force un agent explicite différent (forceAgent)
      if (!existingAgent || existingAgent === fallbackAgent || (forceAgent?.trim() && existingAgent !== newData.agent)) {
        try {
          await db.enseigne.update({
            where: { name },
            data: { agent: newData.agent, type: newData.type },
          });
          enseignesUpdated++;
        } catch {
          // L'enseigne n'existe pas encore, elle sera créée plus bas
        }
      }
    }
    if (enseignesUpdated > 0) {
      console.log(`Enseignes existantes mises à jour (agent réaffecté) : ${enseignesUpdated}`);
    }

    console.log(`Pré-import : ${toInsert.length} à insérer, doublons=${skippedDuplicate}, sans date=${skippedNoDate}, sans montant=${skippedNoAmount}, invalides=${skippedInvalid}`);

    // Mode détection : on renvoie juste le mapping + un aperçu
    if (detectOnly) {
      return NextResponse.json({
        ok: true,
        detectedColumns: headers,
        detectedMapping: mapping,
        preview: {
          totalRows: rows.length,
          validRows: toInsert.length,
          duplicates: skippedDuplicate,
          noDate: skippedNoDate,
          noAmount: skippedNoAmount,
          invalid: skippedInvalid,
          sample: toInsert.slice(0, 3).map((v) => ({
            date: v.date.toISOString().split('T')[0],
            enseigne: v.enseigne,
            type: v.type,
            agent: v.agent,
            amountHT: v.amountHT,
          })),
        },
      });
    }

    // Insertion en lots (batch) pour éviter le timeout Vercel
    // Batch plus gros (500) = moins de round-trips DB = plus rapide
    let inserted = 0, updated = 0;
    const BATCH_SIZE = 500;

    if (!replaceDuplicates) {
      // Mode simple : batch insert avec skipDuplicates (très rapide)
      console.log(`Insertion de ${toInsert.length} ventes en batches de ${BATCH_SIZE}...`);
      for (let i = 0; i < toInsert.length; i += BATCH_SIZE) {
        const batch = toInsert.slice(i, i + BATCH_SIZE);
        try {
          const result = await db.sale.createMany({
            data: batch,
            skipDuplicates: true,
          });
          inserted += result.count;
          console.log(`  Batch ${Math.floor(i / BATCH_SIZE) + 1}/${Math.ceil(toInsert.length / BATCH_SIZE)}: ${result.count} insérées`);
        } catch (e) {
          console.error(`  Batch ${Math.floor(i / BATCH_SIZE) + 1} échoué, fallback 1-par-1:`, e instanceof Error ? e.message : String(e));
          // Si le batch échoue, essaie un par un (plus lent mais resilient)
          for (const v of batch) {
            try { await db.sale.create({ data: v }); inserted++; } catch {}
          }
        }
      }
    } else {
      // Mode replaceDuplicates : un par un (nécessite update)
      console.log(`Mode replaceDuplicates: ${toInsert.length} ventes à traiter...`);
      for (const v of toInsert) {
        try {
          if (replaceDuplicates && existingKeys.has(v.deduplicationKey)) {
            const { deduplicationKey, ...ud } = v;
            await db.sale.updateMany({ where: { deduplicationKey: v.deduplicationKey }, data: ud });
            updated++;
          } else {
            await db.sale.create({ data: v });
            inserted++;
          }
        } catch {
          // Doublon : ignore
        }
      }
    }

    // Nouvelles enseignes — batch insert avec skipDuplicates (très rapide)
    const newEnseignesList = Array.from(newEnseignes.values());
    if (newEnseignesList.length > 0) {
      console.log(`Création de ${newEnseignesList.length} nouvelles enseignes...`);
      try {
        const ensResult = await db.enseigne.createMany({
          data: newEnseignesList,
          skipDuplicates: true,
        });
        console.log(`  ${ensResult.count} enseignes créées`);
      } catch (e) {
        console.error('Erreur création enseignes en batch, fallback 1-par-1:', e instanceof Error ? e.message : String(e));
        for (const e of newEnseignesList) {
          try { await db.enseigne.create({ data: e }); } catch {}
        }
      }
    }

    // Met à jour la période courante si on a importé
    if (inserted > 0 || updated > 0) {
      const nd = toInsert.reduce((max, v) => v.date > max ? v.date : max, toInsert[0].date);
      const dbLatest = await db.sale.findFirst({ orderBy: { date: 'desc' }, select: { date: true } });
      const ol = dbLatest && dbLatest.date > nd ? dbLatest.date : nd;
      await setCurrentPeriod(ol.getFullYear(), ol.getMonth() + 1);
      console.log(`Période mise à jour : ${ol.getMonth() + 1}/${ol.getFullYear()}`);
    }

    const totalSkipped = skippedNoDate + skippedNoAmount + skippedDuplicate + skippedInvalid;
    const detail = [
      `${inserted} nouvelle(s)`,
      updated > 0 ? `${updated} MAJ` : null,
      (!replaceDuplicates && skippedDuplicate > 0) ? `${skippedDuplicate} doublon(s)` : null,
      skippedNoDate > 0 ? `${skippedNoDate} sans date` : null,
      skippedNoAmount > 0 ? `${skippedNoAmount} sans montant` : null,
      skippedInvalid > 0 ? `${skippedInvalid} invalide(s)` : null,
    ].filter(Boolean).join(', ');

    console.log(`Import terminé : ${detail}`);

    return NextResponse.json({
      ok: true,
      result: { inserted, updated, skipped: totalSkipped, total: toInsert.length },
      detail,
      detectedMapping: mapping,
      detectedColumns: headers,
      totals: {
        commission: toInsert.reduce((s, v) => s + v.commission, 0),
        caHT: toInsert.reduce((s, v) => s + v.amountHT, 0),
      },
      // Résumé de la détection intelligente des doublons d'enseignes
      duplicateDetection: {
        totalResolved: canonicalResolutions.size,
        duplicatesResolved: duplicateDetectedCount,
        newClients: Array.from(canonicalResolutions.values()).filter((r) => r.status === 'new').length,
        substitutions: Array.from(canonicalResolutions.values())
          .filter((r) => r.status !== 'exact' && r.status !== 'new')
          .map((r) => ({
            incoming: r.incoming,
            canonical: r.canonical,
            confidence: r.confidence,
            method: r.status,
          })),
      },
    });
  } catch (e) {
    console.error('Erreur non gérée /api/import:', e);
    return NextResponse.json(
      { ok: false, error: e instanceof Error ? e.message : 'Erreur serveur inattendue' },
      { status: 500 }
    );
  }
}

// GET /api/import/detect?file=... : non utilisé (le mapping est détecté dans le POST)
export async function GET(req: NextRequest) {
  return NextResponse.json({
    ok: true,
    message: 'Utilisez POST pour importer un fichier.',
  });
}
